scwin.vScrenID = "ULDSTF05961.xml";
scwin.vScrenTpCD = "";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.TR_JOB;
scwin.vIsurCd, scwin.vIsurNm, scwin.vInputRnd, scwin.vTrJob, scwin.vAcptNo;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};
scwin.fn_SectAhthQualCd_sync = function(nIndex) {
    if (nIndex == "1") {
        if ($c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_1) == "1") {
            dts_SectAhthQualCd_1.DataID = encodeURI("/CodeAction.do?method=listSectAhthQualCd&For=Q&nIndex=1");
            dts_SectAhthQualCd_1.Reset();
            dts_SectAhthInstCd_1.DataID = encodeURI("/CodeAction.do?method=listSectAhthInstCd&For=Q&nIndex=1");
            dts_SectAhthInstCd_1.Reset();
        } else {
            $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_1, "");
            $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_1, "");
        }
    } else if (nIndex == "2") {
        if ($c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_2) == "2") {
            dts_SectAhthQualCd_2.DataID = encodeURI("/CodeAction.do?method=listSectAhthQualCd&For=Q&nIndex=2");
            dts_SectAhthQualCd_2.Reset();
            dts_SectAhthInstCd_2.DataID = encodeURI("/CodeAction.do?method=listSectAhthInstCd&For=Q&nIndex=2");
            dts_SectAhthInstCd_2.Reset();
        } else {
            $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_2, "");
            $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_2, "");
        }
    } else if (nIndex == "3") {
        if ($c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_3) == "3") {
            dts_SectAhthQualCd_3.DataID = encodeURI("/CodeAction.do?method=listSectAhthQualCd&For=Q&nIndex=3");
            dts_SectAhthQualCd_3.Reset();
            dts_SectAhthInstCd_3.DataID = encodeURI("/CodeAction.do?method=listSectAhthInstCd&For=Q&nIndex=3");
            dts_SectAhthInstCd_3.Reset();
        } else {
            $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_3, "");
            $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_3, "");
        }
    } else if (nIndex == "4") {
        if ($c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_4) == "4") {
            dts_SectAhthQualCd_4.DataID = encodeURI("/CodeAction.do?method=listSectAhthQualCd&For=Q&nIndex=4");
            dts_SectAhthQualCd_4.Reset();
            dts_SectAhthInstCd_4.DataID = encodeURI("/CodeAction.do?method=listSectAhthInstCd&For=Q&nIndex=4");
            dts_SectAhthInstCd_4.Reset();
        } else {
            $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_4, "");
            $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_4, "");
        }
    }
};
scwin.fn_CheckForm = function() {
    if (scwin.TR_JOB == 'U') return true;
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사명]를 입력하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_1) == "") {
        $c.win.alert("[벤처기업 인증자격]을 입력하세요.");
        cmb_SECT_AHTH_QUAL_TP_CD_1.focus();
        return false;
    }
    return true;
};
scwin.fn_SetValue = function() {
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_TP_CD_1", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_1));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_TP_CD_2", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_2));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_TP_CD_3", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_3));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_TP_CD_4", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_TP_CD_4));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CD_1", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_CD_1));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CD_2", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_CD_2));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CD_3", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_CD_3));
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CD_4", $c.stf.getObjectValue(cmb_SECT_AHTH_QUAL_CD_4));
    dts_Item.setCellData(1, "SECT_AHTH_INST_CD_1", $c.stf.getObjectValue(cmb_SECT_AHTH_INST_CD_1));
    dts_Item.setCellData(1, "SECT_AHTH_INST_CD_2", $c.stf.getObjectValue(cmb_SECT_AHTH_INST_CD_2));
    dts_Item.setCellData(1, "SECT_AHTH_INST_CD_3", $c.stf.getObjectValue(cmb_SECT_AHTH_INST_CD_3));
    dts_Item.setCellData(1, "SECT_AHTH_INST_CD_4", $c.stf.getObjectValue(cmb_SECT_AHTH_INST_CD_4));
    dts_Item.setCellData(1, "DESIGN_DD_1", $c.stf.getObjectValue(edt_DESIGN_DD_1));
    dts_Item.setCellData(1, "DESIGN_DD_2", $c.stf.getObjectValue(edt_DESIGN_DD_2));
    dts_Item.setCellData(1, "DESIGN_DD_3", $c.stf.getObjectValue(edt_DESIGN_DD_3));
    dts_Item.setCellData(1, "DESIGN_DD_4", $c.stf.getObjectValue(edt_DESIGN_DD_4));
    dts_Item.setCellData(1, "VALID_STRT_DD_1", $c.stf.getObjectValue(edt_VALID_STRT_DD_1));
    dts_Item.setCellData(1, "VALID_STRT_DD_2", $c.stf.getObjectValue(edt_VALID_STRT_DD_2));
    dts_Item.setCellData(1, "VALID_STRT_DD_3", $c.stf.getObjectValue(edt_VALID_STRT_DD_3));
    dts_Item.setCellData(1, "VALID_STRT_DD_4", $c.stf.getObjectValue(edt_VALID_STRT_DD_4));
    dts_Item.setCellData(1, "VALID_END_DD_1", $c.stf.getObjectValue(edt_VALID_END_DD_1));
    dts_Item.setCellData(1, "VALID_END_DD_2", $c.stf.getObjectValue(edt_VALID_END_DD_2));
    dts_Item.setCellData(1, "VALID_END_DD_3", $c.stf.getObjectValue(edt_VALID_END_DD_3));
    dts_Item.setCellData(1, "VALID_END_DD_4", $c.stf.getObjectValue(edt_VALID_END_DD_4));
    dts_Item.setCellData(1, "REMK_1", $c.stf.getObjectValue(txa_REMK_1));
    dts_Item.setCellData(1, "REMK_2", $c.stf.getObjectValue(txa_REMK_2));
    dts_Item.setCellData(1, "REMK_3", $c.stf.getObjectValue(txa_REMK_3));
    dts_Item.setCellData(1, "REMK_4", $c.stf.getObjectValue(txa_REMK_4));
    dts_Item.setCellData(1, "INPUTRND", scwin.vInputRnd);
};
scwin.fn_trs = function() {

};
scwin.fn_save = function() {
    scwin.TR_JOB = scwin.vTrJob;
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        /*	if(vTrJob == "U"){
        		dts_Item.UserStatus(1) = TB_JOB_UPDATE;
        	} else {
        		dts_Item.UserStatus(1) = TB_JOB_INSERT;
        	}*/

        scwin.fn_SetValue();
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        trs_Save.Action = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveSectAhthQual";
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Item,I:pFile1=dts_File)";
        trs_Save.Post();
    }
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.fn_filedown = function(dtsObj) {
    var vBzProcsNo = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "BZ_PROCS_NO");
    var vDisclsDocNo = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    var attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (vBzProcsNo != '') location.href = "/filedownload.do?file_id=" + vBzProcsNo + "&attach_seq=" + attach_seq + "&gubun=23";

    else if (vDisclsDocNo != '') location.href = "/filedownload.do?file_id=" + vDisclsDocNo + "&attach_seq=" + attach_seq + "&gubun=12";
};
scwin.fn_file_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=SECT_TYP_CHG_CERT_ATTACHFILE_OUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.scttypchg.select.ahthqual.attachfile";
    url += "&{P}param01=" + scwin.vAcptNo;
    url += "&{P}param02=" + scwin.vIsurCd + $c.ut.lpad(scwin.vInputRnd, 9, "0");
    dts_File.DataID = encodeURI(url);
    dts_File.Reset();
};
scwin.fn_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=SECT_AHTH_QUAL_MGM_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.scttypchg.ahthqual.select.detail";
    url += "&{P}param01=" + scwin.vIsurCd;
    url += "&{P}param02=" + scwin.vInputRnd;
    url += "&{P}param03=" + scwin.vIsurCd;
    url += "&{P}param04=" + scwin.vInputRnd;
    url += "&{P}param05=" + scwin.vIsurCd;
    url += "&{P}param06=" + scwin.vInputRnd;
    url += "&{P}param07=" + scwin.vIsurCd;
    url += "&{P}param08=" + scwin.vInputRnd;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_file_read_sync();
    $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_1, dts_Item.getCellData(1, "SECT_AHTH_QUAL_CD_1"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_1, dts_Item.getCellData(1, "SECT_AHTH_INST_CD_1"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_2, dts_Item.getCellData(1, "SECT_AHTH_QUAL_CD_2"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_2, dts_Item.getCellData(1, "SECT_AHTH_INST_CD_2"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_3, dts_Item.getCellData(1, "SECT_AHTH_QUAL_CD_3"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_3, dts_Item.getCellData(1, "SECT_AHTH_INST_CD_3"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_QUAL_CD_4, dts_Item.getCellData(1, "SECT_AHTH_QUAL_CD_4"));
    $c.stf.setObjectValue(cmb_SECT_AHTH_INST_CD_4, dts_Item.getCellData(1, "SECT_AHTH_INST_CD_4"));
};
scwin.fn_updateUI = function() {
    //수정불가값
    txb_ISUR_CD.setDisabled(true);
    cmb_SECT_AHTH_QUAL_TP_CD_1.setDisabled(true);
    cmb_SECT_AHTH_QUAL_TP_CD_2.setDisabled(true);
    cmb_SECT_AHTH_QUAL_TP_CD_3.setDisabled(true);
    cmb_SECT_AHTH_QUAL_TP_CD_4.setDisabled(true);
    cmb_SECT_AHTH_QUAL_CD_1.setDisabled(true);
    cmb_SECT_AHTH_QUAL_CD_2.setDisabled(true);
    cmb_SECT_AHTH_QUAL_CD_3.setDisabled(true);
    cmb_SECT_AHTH_QUAL_CD_4.setDisabled(true);
    cmb_SECT_AHTH_INST_CD_1.setDisabled(true);
    cmb_SECT_AHTH_INST_CD_2.setDisabled(true);
    cmb_SECT_AHTH_INST_CD_3.setDisabled(true);
    cmb_SECT_AHTH_INST_CD_4.setDisabled(true);
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_DESIGN_DD_1_onclick = function() {
    popUpCalendar2(edt_DESIGN_DD_1);
};
