scwin.cmb_SECT_AHTH_QUAL_TP_CD_1_OnSelChange = function() {
    scwin.fn_SectAhthQualCd_sync("1");
};
scwin.cmb_SECT_AHTH_QUAL_TP_CD_2_OnSelChange = function() {
    scwin.fn_SectAhthQualCd_sync("2");
};
scwin.cmb_SECT_AHTH_QUAL_TP_CD_3_OnSelChange = function() {
