    scwin.fn_save();
};
scwin.btn_update_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    //fn_read_sync();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_File.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_File.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_File, dts_File.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_File, dts_File.getRowPosition());
};
scwin.grd_ATTACH_FILE_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (dts_File.getRowStatus(dts_File.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_File);
    }
};
scwin.gform_onload = function() {
    dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SECT_AHTH_QUAL_MGM_INOUT";
    dts_Item.reset();
    dts_Item.insertRow();
    //dts_File.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    $c.stf.showObj(file_name, false);
    var parentWin = $c.frame.path("../");
    scwin.vIsurCd = parentWin.gIsurCd;
    scwin.vIsurNm = parentWin.gIsurNm;
    scwin.vInputRnd = parentWin.gInputRnd;
    scwin.vTrJob = parentWin.gGubnStat;
    scwin.vAcptNo = parentWin.gAcptNo;
    if (scwin.vTrJob == "U") {
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.vIsurCd);
        $c.stf.setObjectValue(txb_COM_NM, scwin.vIsurNm);
        txb_ISUR_CD.setReadOnly(true);
        btn_lineadd.src = "../img/btn_fileadd_dis.gif";
        btn_lineadd.setDisabled(true);
        btn_linedelete.src = "../img/btn_filedelete_dis.gif";
        btn_linedelete.setDisabled(true);
        //btn_save.src = "../img/btn_save_d.gif";
        //btn_save.disabled = true;
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
        btn_save.src = "../img/btn_save_d.gif";
        btn_save.setDisabled(true);
        scwin.fn_updateUI();
        scwin.fn_read_sync();
    } else {
        btn_update.src = "../img/btn_modify_d.gif";
        btn_update.setDisabled(true);
    }
};
